#!/usr/bin/env python3
"""Is the 65-entry ellBands table generated by a TABLELESS recurrence?

Candidate rule (integer arithmetic only):
    B_1    = 8918,  E_1 = 9442        (seed: the first band is special)
    w_j    = min(floor(E_j/10) + 1, NHI - E_j)      for j >= 2, B_j = E_{j-1}
    L_1    = 9603098                   (seed)
    L_{j+1} = L_j + ceil(2^20 * w / B)
    T_j    = floor(99 * 2^70 / (1000 * L_j))
"""
import sys
sys.path.insert(0, '.')
from liouville_bands import ellBands

NLO, NHI = 8918, 4000000
ANCHOR = 9541486

# --- 1. widths ---
starts = [NLO]
for (w, T, L) in ellBands:
    starts.append(starts[-1] + w)
print(f"bands {len(ellBands)}, final start {starts[-1]} (want {NHI})")

badw = []
for j in range(1, len(ellBands)):
    B = starts[j]
    pred = min(B // 10 + 1, NHI - B)
    if pred != ellBands[j][0]:
        badw.append((j, B, pred, ellBands[j][0]))
print(f"width rule w_j = min(B//10 + 1, NHI-B) for j>=2: {len(badw)} mismatches")
for b in badw[:5]:
    print("   ", b)
print(f"  band 1: width {ellBands[0][0]} vs rule {min(NLO//10+1, NHI-NLO)} (special, seeded)")

# --- 2. L chain ---
badL = []
L = ANCHOR
for j, (w, T, Lj) in enumerate(ellBands):
    B = starts[j]
    L = L + -(-(1 << 20) * w // B)
    if L != Lj:
        badL.append((j, B, w, L, Lj))
print(f"L chain L_j = L_{{j-1}} + ceil(2^20*w/B) from anchor {ANCHOR}: "
      f"{len(badL)} mismatches")
for b in badL[:5]:
    print("   ", b)

# --- 3. T from L ---
badT = []
for j, (w, T, Lj) in enumerate(ellBands):
    pred = 99 * (1 << 70) // (1000 * Lj)
    if pred != T:
        badT.append((j, Lj, pred, T))
print(f"T_j = floor(99*2^70/(1000*L_j)): {len(badT)} mismatches")
for b in badT[:5]:
    print("   ", b)

# --- 4. the machine's ladder, seeded at (E=9442, Lb=9603098) ---
E, Lb = 9442, 9603098
seq = [(NLO, 9442, 9603098)]
ok = True
for j in range(1, len(ellBands)):
    B = E
    w = min(B // 10 + 1, NHI - B)
    Lb = Lb + -(-(1 << 20) * w // B)
    E = B + w
    if Lb != ellBands[j][2] or E != starts[j + 1]:
        ok = False
        print(f"  machine ladder diverges at j={j}: E={E} want {starts[j+1]},"
              f" Lb={Lb} want {ellBands[j][2]}")
print(f"machine ladder reproduces ellBands exactly: {ok}; final E={E} Lb={Lb}")
print(f"max L_j = {max(b[2] for b in ellBands)} "
      f"({max(b[2] for b in ellBands).bit_length()} bits)")
print(f"max T_j = {max(b[1] for b in ellBands)} "
      f"({max(b[1] for b in ellBands).bit_length()} bits)")
